def valid_date(date):
    """Validate a date string in the format mm-dd-yyyy."""
    if not date:
        return False

    parts = date.split('-')
    if len(parts) != 3:
        return False

    month_str, day_str, year_str = parts

    # All components must be non-empty and consist only of digits
    if not (month_str.isdigit() and day_str.isdigit() and year_str.isdigit()):
        return False

    month = int(month_str)
    day = int(day_str)

    if month < 1 or month > 12:
        return False

    if month in (1, 3, 5, 7, 8, 10, 12):
        max_days = 31
    elif month in (4, 6, 9, 11):
        max_days = 30
    else:  # month == 2
        max_days = 29

    if day < 1 or day > max_days:
        return False

    return True
